/**
 * The matrix: one row per candidate at horizon `h` ("lead" = the horizon its verdict is about), one
 * column per test year; a cell is that year's signed rank IC ×100 (0.10 shows as +10).
 */
export function screenMatrix(doc: ScreenDoc, h: "lead" | number = "lead"): RunMatrix {
	const years = new Set<number>();
	for (const f of doc.features) for (const t of f.trials) for (const fold of t.folds) years.add(fold.year);
	const folds = [...years].sort().map((year) => ({ id: String(year), year }));
	return {
		phase: "screen",
		stresses: [{ id: "ic", label: "" }],
		folds,
		rows: doc.features.map((f) => {
			const trial = h === "lead" ? leadTrial(f) : f.trials.find((t) => t.h === h);
			return {
				candidate: f.code,
				label: trial ? `${trial.h}${doc.unit}` : "—",
				cells: (trial?.folds ?? [])
					.filter((fold) => fold.ic != null)
					.map((fold) => ({
						stress: "ic",
						year: fold.year,
						diff: fold.ic! * 100,
						gate0: "passed" as const,
					})),
			};
		}),
		note: "",
	};
}

const pad = (v: number) => String(v).padStart(2, "0");
/** `2022.03.14` (UTC). Dots, not dashes: the line chart reads a label ending in `-01` as a January tick. */
export function dateLabel(ms: number): string {
	const d = new Date(ms);
	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
}

/** Round axis values (1·2·5 × 10ⁿ) covering [lo, hi], about `count` of them: the largest step not over 1.25 × the even split. */
export function niceTicks(lo: number, hi: number, count = 5): number[] {
	const raw = (hi - lo || 1) / count;
	const pow = 10 ** Math.floor(Math.log10(raw));
	const step = ([10, 5, 2, 1].find((m) => m * pow <= raw * 1.25) ?? 1) * pow;
	const out: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(Math.round(v / step) * step);
	return out;
}

export interface CurveView {
	labels: string[];
	/** Percent; 100 = the rule earned its whole starting size once over. */
	rule: number[];
	hold: number[];
	ticks: number[];
}

/** Percent view of a trial's curve; null when the trial has none (no rebalance ran, or an older result file). */
export function curveView(trial: ScreenTrial | undefined): CurveView | null {
	const c = trial?.curve;
	if (!c || c.t.length < 2) return null;
	const run = (values: (number | null)[]) => {
		let last = 0;
		return values.map((v) => (last = v == null ? last : v * 100));
	};
	const rule = run(c.rule);
	const hold = run(c.hold);
	return {
		labels: c.t.map(dateLabel),
		rule,
		hold,
		ticks: niceTicks(Math.min(0, ...rule, ...hold), Math.max(0, ...rule, ...hold)),
	};
}

export interface RuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	/** Word next to the tile's state icon. */
	label: string;
	time?: string;
	tip: string;
	kind: "indicator" | "regime" | "direction" | "fill" | "hold";
}

/**
 * The sign rule the screen ran for one trial, as decision-path tiles: indicator → regime → direction (entry),
 * cost (fill), horizon (exit). Everything is a document field; the rule itself is `screen.rs` `run_trial`.
 */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, t: ScreenTrial): RuleTile[] {
	const word = doc.unit === "H" ? "시간" : "일";
	const fixed = doc.fixed_sign != null;
	const sign = fixed ? (doc.fixed_sign as number) : t.train_sign;
	const flips = !fixed && new Set(t.folds.map((x) => x.train_sign)).size > 1;
	const [up, down] = sign >= 0 ? ["롱", "숏"] : ["숏", "롱"];
	const bp = (doc.cost_per_side * 1e4).toFixed(0);
	const tiles: RuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			kind: "indicator",
			name: featureName(f),
			label: f.tradeable === false ? "참고 지표" : "지표",
			tip: `${featureDef(f) || f.feature}. 결정 시각 전에 공개된 값만 쓴다.${f.tradeable === false ? " 체결이 실시간 공개되지 않아 참고 행이다." : ""}`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			kind: "regime",
			name: "200일선 아래",
			label: "국면",
			tip: "종가가 200일 평균 아래인 날에만 포지션을 잡고, 아니면 쉰다.",
		});
	}
	tiles.push(
		{
			id: "direction",
			group: "entry",
			kind: "direction",
			name: `기준 위면 ${up}`,
			label: flips ? "부호 바뀜" : sign >= 0 ? "순방향" : "역추세",
			tip: fixed
				? `부호를 +1로 고정했다. 값이 0보다 크면 ${up}, 작으면 ${down}을 잡는다.`
				: `학습 구간에서 지표와 수익의 순위 상관 부호가 ${sign >= 0 ? "+" : "−"}라서, 학습 중앙값보다 높으면 ${up}, 낮으면 ${down}을 잡는다.${flips ? " 시험 연도마다 학습 구간이 달라 부호가 바뀐 해가 있고, 이 칸은 마지막 해 기준이다." : ""}`,
		},
		{
			id: "fill",
			group: "fill",
			kind: "fill",
			name: `편도 ${bp}bp`,
			label: "비용",
			time: "+ 펀딩",
			tip: `포지션을 바꿀 때마다 한쪽 ${bp}bp를 낸다(보수적으로 2배). 롱은 실제 펀딩비를 내고 숏은 받으며, 펀딩을 모르는 구간은 양쪽이 기본값을 낸다.`,
		},
		{
			id: "hold",
			group: "exit",
			kind: "hold",
			name: `${t.h}${doc.unit} 보유`,
			label: "재판단",
			tip: `손절이나 목표 없이 ${t.h}${word}마다 새 값으로 포지션을 다시 정한다. 방향이 그대로면 거래 비용은 들지 않는다.`,
		},
	);
	return tiles;
}

