/**
 * The matrix: one row per candidate at horizon `h` ("lead" = the horizon its verdict is about), one
 * column per test year; a cell is that year's signed rank IC ×100 (0.10 shows as +10).
 */
export function screenMatrix(doc: ScreenDoc, h: "lead" | number = "lead"): RunMatrix {
	const years = new Set<number>();
	for (const f of doc.features) for (const t of f.trials) for (const fold of t.folds) years.add(fold.year);
	const folds = [...years].sort().map((year) => ({ id: String(year), year }));
	return {
		phase: "screen",
		stresses: [{ id: "ic", label: "" }],
		folds,
		rows: doc.features.map((f) => {
			const trial = h === "lead" ? leadTrial(f) : f.trials.find((t) => t.h === h);
			return {
				candidate: f.code,
				label: trial ? `${trial.h}${doc.unit}` : "—",
				cells: (trial?.folds ?? [])
					.filter((fold) => fold.ic != null)
					.map((fold) => ({
						stress: "ic",
						year: fold.year,
						diff: fold.ic! * 100,
						gate0: "passed" as const,
					})),
			};
		}),
		note: "",
	};
}

const pad = (v: number) => String(v).padStart(2, "0");
/** `2022.03.14` (UTC). Dots, not dashes: the line chart reads a label ending in `-01` as a January tick. */
export function dateLabel(ms: number): string {
	const d = new Date(ms);
	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
}

/** Round axis values (1·2·5 × 10ⁿ) covering [lo, hi], about `count` of them: the largest step not over 1.25 × the even split. */
export function niceTicks(lo: number, hi: number, count = 5): number[] {
	const raw = (hi - lo || 1) / count;
	const pow = 10 ** Math.floor(Math.log10(raw));
	const step = ([10, 5, 2, 1].find((m) => m * pow <= raw * 1.25) ?? 1) * pow;
	const out: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(Math.round(v / step) * step);
	return out;
}

export interface CurveView {
	labels: string[];
	/** Percent; 100 = the rule earned its whole starting size once over. */
	rule: number[];
	hold: number[];
	ticks: number[];
}

/** Percent view of a trial's curve; null when the trial has none (no rebalance ran, or an older result file). */
export function curveView(trial: ScreenTrial | undefined): CurveView | null {
	const c = trial?.curve;
	if (!c || c.t.length < 2) return null;
	const run = (values: (number | null)[]) => {
		let last = 0;
		return values.map((v) => (last = v == null ? last : v * 100));
	};
	const rule = run(c.rule);
	const hold = run(c.hold);
	return {
		labels: c.t.map(dateLabel),
		rule,
		hold,
		ticks: niceTicks(Math.min(0, ...rule, ...hold), Math.max(0, ...rule, ...hold)),
